<?php
declare(strict_types=1);
if(!defined('ACADEMY_ROOT')){http_response_code(403);exit;}
/** Held separately from lesson quizzes; disclosed only after exam submission. */
function academy_final_cases(): array
{
    return [
    'melas'=>[
      ['me-qualification','Ο υπεύθυνος συντήρησης επιβεβαιώνει 4.200 πάνελ, αλλά η πώληση χρειάζεται απόφαση του ιδιοκτήτη που δεν έχει ερωτηθεί. Ποιο είναι το σωστό επόμενο βήμα;','Διερεύνηση εξουσιοδότησης και πραγματικής πρόθεσης με τον αρμόδιο, χωρίς ακόμη qualified fee.','Έγκριση επειδή η ποσότητα και η θέση του συνομιλητή αρκούν ως τεκμήρια.','Έγκριση υπό την αίρεση ότι ο ιδιοκτήτης δεν θα διαφωνήσει αργότερα.','Απόρριψη ως άκυρου lead χωρίς δυνατότητα συμπλήρωσης.','Η τεχνική γνώση δεν ισοδυναμεί με αρμοδιότητα πώλησης. Η ευκαιρία μπορεί να συμπληρωθεί.'],
      ['me-commissions','Εγκρίθηκε lead €80 για 4.500 πάνελ. Αγοράστηκαν 3.600, αλλά ο πωλητής πληρώθηκε για 2.400. Ποια αμοιβή έχει θεμελιωθεί μέχρι τώρα;','€1.520, πριν από τυχόν καταχωρισμένες εξοφλήσεις προς τον συνεργάτη.','€2.240, επειδή αυτή είναι η ποσότητα της αγοράς.','€2.780, επειδή αυτή ήταν η αρχική ποσότητα του lead.','€1.440, επειδή η προμήθεια πάνελ αντικαθιστά την αμοιβή lead.','80 + 2.400 × 0,60 = 1.520. Η εξόφληση του συνεργάτη είναι διαφορετικό γεγονός.'],
      ['me-services','Ο πελάτης αναφέρει πτώση παραγωγής μετά από εργασίες καθαρισμού και ζητά τιμή επισκευής. Ποια συνέχεια είναι πιο κατάλληλη;','Καταγράφω χρόνο, στοιχεία παραγωγής και συμβάντα και ζητώ τεχνική διάγνωση πριν οριστικοποιηθεί λύση.','Προτείνω νέο καθαρισμό ως λιγότερο δαπανηρό πρώτο βήμα χωρίς άλλες πληροφορίες.','Αποδίδω τη βλάβη στον προηγούμενο συνεργάτη ώστε να οριοθετηθεί ευθύνη.','Δίνω εκτίμηση αντικατάστασης πάνελ βάσει μόνο της ποσοστιαίας πτώσης.','Ο πωλητής καταγράφει την ανάγκη· η τεχνική αιτία και το αντικείμενο απαιτούν διερεύνηση.'],
      ['me-negotiation','Ο πωλητής ζητά άμεση δέσμευση τιμής αλλά λείπουν μεταφορικά και στοιχεία κατάστασης. Ποια ανταπόκριση προφυλάσσει τη συμφωνία;','Ζητώ τα κρίσιμα στοιχεία και ορίζω χρόνο επανόδου για εγκεκριμένη συνολική πρόταση.','Αποδέχομαι ενδεικτικά, αφού τα μεταφορικά θα υπολογιστούν πριν την παραλαβή.','Συμφωνώ μόνο την τιμή πάνελ και αφήνω προφορικά τα υπόλοιπα έξοδα.','Μειώνω αυθαίρετα την ποσότητα για να αντισταθμίσω τα άγνωστα κόστη.','Η δέσμευση χρειάζεται σαφή στοιχεία, ευθύνες και εγκεκριμένους όρους.']
