    'distillogic'=>[
      ['di-discovery','Ξενοδοχείο έχει website, αλλά χάνει αιτήματα ομαδικών κρατήσεων. Τι πρέπει να διερευνηθεί πρώτο;','Η σημερινή διαδρομή αιτήματος, ποιος απαντά και πού χάνεται η πληροφορία.','Η δυνατότητα πλήρους αντικατάστασης, επειδή το υπάρχον site δεν φέρνει όλα τα αιτήματα.','Η ακριβής έκπτωση για να προλάβουμε το υφιστάμενο agency.','Το χρώμα του νέου κουμπιού, ώστε να παρουσιαστεί άμεσα λύση.','Η ανάγκη μπορεί να αφορά συγκεκριμένη διαδρομή και όχι πλήρη ανακατασκευή.'],
      ['di-followup','Η γραμματεία δίνει email και λέει «ο διευθυντής κοιτάζει προτάσεις την Παρασκευή», χωρίς να έχει συμφωνηθεί επικοινωνία μαζί του. Τι έχει επιτευχθεί;','Διαδρομή προς τον αρμόδιο, όχι επιβεβαιωμένο ραντεβού ή εμπορική αποδοχή.','Ραντεβού Παρασκευής με τον διευθυντή, έστω χωρίς ακριβή ώρα.','Qualified ευκαιρία, επειδή δόθηκε κανάλι και ημέρα.','Άδεια για εβδομαδιαίες προτάσεις μέχρι να ληφθεί απάντηση.','Διαχωρίζουμε πληροφορία από συμφωνία και καταγράφουμε το πραγματικό επόμενο βήμα.'],
      ['di-performance','Από 30 ουσιαστικές συνομιλίες συμφωνήθηκαν 9 παρουσιάσεις. Έγιναν οι 6 και οι 3 εκκρεμούν. Ποια αναφορά είναι ακριβής;','30% συμφωνία παρουσίασης· η πραγματοποίηση των 9 δεν έχει κλείσει ακόμη ως cohort.','20% συμφωνία παρουσίασης και 100% πραγματοποίηση όσων προγραμματίστηκαν.','67% μετατροπή συνομιλίας σε παρουσίαση, χωρίς ανάγκη αναφοράς των εκκρεμών.','30% πωλήσεις, επειδή η συμφωνία παρουσίασης είναι το εμπορικό αποτέλεσμα.','9/30 είναι συμφωνίες παρουσίασης. Οι εκκρεμείς περιπτώσεις δεν χαρακτηρίζονται αποτυχίες ή πωλήσεις.'],
      ['di-compliance','Μια επαφή ζήτησε διαγραφή από προωθητικές επικοινωνίες, αλλά εμφανίζεται σε νέα αγορασμένη λίστα. Τι κάνεις;','Εφαρμόζω την καταγεγραμμένη αντίρρηση και ενημερώνω τον υπεύθυνο για τη νέα λίστα.','Επιτρέπω μία ενημερωτική κλήση επειδή η λίστα έχει μεταγενέστερη ημερομηνία.','Στέλνω πρώτα email ώστε να επιβεβαιώσει ξανά την αντίρρηση.','Αναθέτω την επαφή σε άλλον υπάλληλο που δεν είχε λάβει το αίτημα.','Η νέα πηγή δεν αναιρεί την αντίρρηση ούτε επιτρέπει παράκαμψη μέσω άλλου εργαζομένου.']
    ],
    'crm'=>[
      ['crm-protection','Ο εγκρίνων ζητά να δηλωθεί ως ιδιοκτήτης ώστε να αναλάβει την επόμενη συζήτηση. Ποια μεταβολή είναι σωστή;','Καταγράφεται ο συντονισμός χωρίς αλλαγή του αρχικού δικαιούχου της ευκαιρίας.','Αλλάζει προσωρινά ο ιδιοκτήτης και επανέρχεται όταν κλείσει η αγορά.','Μεταφέρεται μόνο η αμοιβή €80 στον εγκρίνοντα.','Δημιουργείται δεύτερο lead στον εγκρίνοντα για διατήρηση και των δύο καρτελών.','Η ανάληψη εργασίας δεν μεταφέρει την κατοχύρωση ή τον δικαιούχο.'],
      ['crm-entry','Καταχωρίστηκαν 2.500 πάνελ και συνολική ζητούμενη τιμή €37.500. Κατόπιν ο πωλητής διορθώνει μόνο την ποσότητα σε 2.000 και επιμένει στην ίδια συνολική τιμή. Τι ελέγχεις;','Σύνολο €37.500 και τιμή €18,75 ανά πάνελ, με σημείωση της επιβεβαιωμένης διόρθωσης.','Σύνολο €30.000 ώστε να μείνει η αρχική τιμή μονάδας.','Διατήρηση και των αρχικών αριθμών μέχρι να υπάρξει αγορά.','Δεύτερο lead με 500 πάνελ ώστε να συμφωνούν τα σύνολα.','Προηγείται η πραγματική διευκρίνιση του πωλητή· ο υπολογισμός δεν αποφασίζει εμπορικούς όρους.'],
      ['crm-finance','Ο συνεργάτης βλέπει προμήθεια πληρωτέα €900 και υποστηρίζει ότι το σύστημα δείχνει πως τα πήρε. Τι διευκρινίζεις;','Πληρωτέα σημαίνει καταγεγραμμένη οφειλή, όχι απόδειξη εξόφλησης προς αυτόν.','Το ποσό εξοφλήθηκε μόλις πληρώθηκε ο πωλητής.','Η ένδειξη σημαίνει ότι το lead παραμένει προς έγκριση.','Πρέπει να προστεθεί δεύτερη εγγραφή για να εμφανιστεί η πληρωμή.','Έσοδο, γέννηση προμήθειας και εξόφληση συνεργάτη είναι διαφορετικά γεγονότα.'],
      ['crm-proposals','Μετά το CEO Approval αλλάζει μόνο ο λογαριασμός πληρωμής στο PDF. Ποια ενέργεια διατηρεί ελέγξιμη έγκριση;','Νέα έκδοση εγγράφου και έγκριση της συγκεκριμένης τελικής έκδοσης.','Αντικατάσταση του PDF επειδή δεν αλλάζει το συμφωνημένο ποσό.','Επισύναψη του παλιού κωδικού έγκρισης στο νέο PDF.','Αποστολή με σημείωση ότι οι υπόλοιποι όροι παραμένουν ίδιοι.','Η έγκριση συνδέεται με το αρχείο, όχι μόνο με την τιμή του.']
    ],
    'crm-distillogic'=>[
      ['dcrm-customer','Βρίσκεις παλαιά εταιρική καρτέλα με διαφορετικό τηλέφωνο και νέο υπεύθυνο. Τι κάνεις πριν δημιουργήσεις νέα;','Επιβεβαιώνω την ταυτότητα της εταιρείας και ενημερώνω τα στοιχεία με διατήρηση του ιστορικού.','Δημιουργώ νέα επειδή άλλαξε ο άνθρωπος επικοινωνίας.','Μετονομάζω την παλιά στο όνομα του νέου υπευθύνου.','Διαγράφω την παλιά ώστε να μην υπάρχουν δύο αριθμοί.','Η εταιρική ταυτότητα δεν ταυτίζεται με τον εκάστοτε συνομιλητή.'],
      ['dcrm-communication','Ο πελάτης θέλει υπενθύμιση σε τρεις εβδομάδες μετά από εσωτερική σύσκεψη. Ποια καταχώριση εξασφαλίζει συνέχεια;','Συγκεκριμένη ημερομηνία, λόγος επανόδου, επόμενο βήμα και υπεύθυνος.','Μόνο υψηλό ενδιαφέρον ώστε να παραμένει ψηλά στη λίστα.','Μεταφορά σε στάδιο πρότασης επειδή θα συζητηθεί εσωτερικά.','Σημείωση «επικοινωνία αργότερα» χωρίς ημερομηνία για ευελιξία.','Η χρήσιμη υπενθύμιση περιλαμβάνει χρόνο και περιεχόμενο, όχι μόνο εκτίμηση ενδιαφέροντος.'],
      ['dcrm-web-handoff','Η ομάδα υλοποίησης λαμβάνει brief «website με προϊόντα», αλλά ο πελάτης περίμενε online πληρωμές. Τι αποδεικνύει το κενό;','Δεν διευκρινίστηκε αν ζητήθηκε κατάλογος, αίτημα προσφοράς ή πλήρες ηλεκτρονικό κατάστημα.','Κάθε αναφορά σε προϊόντα περιλαμβάνει πληρωμές ως αυτονόητη λειτουργία.','Ο πελάτης άλλαξε οπωσδήποτε αντικείμενο μετά τη συμφωνία.','Αρκεί να προστεθεί σύνδεσμος τραπεζικού λογαριασμού.','Το scope πρέπει να περιγράφει λειτουργικές διαδρομές και ρητά όσα περιλαμβάνονται.'],
      ['dcrm-proposals','Ένα demo εγκρίθηκε αισθητικά από τον υπεύθυνο marketing, αλλά οι εμπορικοί όροι περιμένουν τον διευθυντή. Πώς αποτυπώνεται;','Θετικό feedback στο demo, με ανοικτή απόφαση αρμόδιου για τους όρους.','Ολοκληρωμένη συμφωνία αφού ο υπεύθυνος marketing έδωσε έγκριση.','Τελική έγκριση CEO αντί του πελάτη ώστε να ξεκινήσει το έργο.','Κλειστή χαμένη ευκαιρία επειδή δεν εγκρίθηκαν αμέσως οι όροι.','Άλλο η αισθητική αποδοχή και άλλο η εξουσιοδοτημένη εμπορική απόφαση.']
    ]];
}
function academy_final_questions(): array
{
    $out=[];$critical=['me-qualification','crm-protection','crm-proposals','dcrm-proposals','di-compliance'];
    foreach(academy_catalog() as $pillarId=>$pillar) {
        $rows=[];
        foreach(academy_final_cases()[$pillarId] as $case){$id=array_shift($case);$rows[]=[$id,academy_challenge_question($case,'final:'.$id),'case'];}
        $pool=array_filter($pillar['lessons'],fn($l)=>($l['type']??'')!=='lab');$keys=array_keys($pool);shuffle($keys);
        foreach(array_slice($keys,0,4) as $id){$lesson=$pool[$id];$rows[]=[$id,$lesson['quiz'][random_int(0,count($lesson['quiz'])-1)],'lesson'];}
        foreach($rows as [$id,$q,$source]) {
            $order=range(0,count($q[1])-1);shuffle($order);
            $out[]=['curriculum'=>37,'pillar'=>$pillarId,'lesson'=>$id,'source'=>$source,'prompt'=>$q[0],'options'=>array_map(fn($i)=>$q[1][$i],$order),'correct'=>array_search($q[2],$order,true),'why'=>$q[3],'critical'=>in_array($id,$critical,true)];
        }
    }
    shuffle($out);return $out;
}
